{
  "mode": "server",
  "server": "user-Google-sheets",
  "serverStatus": "ready",
  "tools": [
    {
      "tool": "get_spreadsheet",
      "description": "Returns the spreadsheet content for the given spreadsheet. Returns titles, sheet names, grid properties, and other metadata for the given spreadsheet ID. Also returns full grid data if requested. Corresponds to spreadsheets.get in the REST API: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets/get",
      "inputSchema": {
        "type": "object",
        "properties": {
          "fields": {
            "description": "Optional. A field mask to specify which properties to return of the Spreadsheets API, see https://developers.google.com/workspace/sheets/api/guides/field-masks for more on how to use the field masks. IMPORTANT: Use hierarchical paths based on the response JSON structure of the Sheets API. - For example, to get the sheet title and ID, use 'sheets.properties(sheetId,title)' instead of 'title,sheetId'. - Only include the fields you need. - To get tables, use: 'sheets.tables' or 'sheets(tables,properties)' - To get sheet titles and IDs, use: 'sheets.properties(sheetId,title)'",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "includeGridData": {
            "description": "True if grid data should be returned.",
            "type": "boolean"
          },
          "ranges": {
            "description": "Optional. The [A1 notation or R1C1 notation](https://developers.google.com/workspace/sheets/api/guides/concepts) of the ranges to retrieve from the spreadsheet. If not specified, the entire spreadsheet is returned.",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "spreadsheetId": {
            "description": "Required. The ID of the spreadsheet to request.",
            "type": "string"
          }
        },
        "required": [
          "spreadsheetId"
        ]
      }
    },
    {
      "tool": "get_values",
      "description": "Returns a range of values from a spreadsheet. Corresponds to spreadsheets.values.get in the REST API: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets.values/get",
      "inputSchema": {
        "type": "object",
        "properties": {
          "range": {
            "description": "Required. The [A1 notation or R1C1 notation](https://developers.google.com/workspace/sheets/api/guides/concepts) of the range to retrieve values from.",
            "type": "string"
          },
          "spreadsheetId": {
            "description": "Required. The ID of the spreadsheet to retrieve data from.",
            "type": "string"
          }
        },
        "required": [
          "spreadsheetId",
          "range"
        ]
      }
    },
    {
      "tool": "insert_dimension",
      "description": "Inserts rows or columns in a sheet at a particular index. Corresponds to an InsertDimensionRequest in the spreadsheets.batchUpdate REST API: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets/request",
      "inputSchema": {
        "type": "object",
        "properties": {
          "dimension": {
            "description": "Required. The dimension to insert.",
            "enum": [
              "DIMENSION_UNSPECIFIED",
              "COLUMNS",
              "ROWS"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "The default value, do not use.",
              "Operates on the columns of a sheet.",
              "Operates on the rows of a sheet."
            ]
          },
          "endIndex": {
            "description": "Required. The 0-based end index of the insertion (exclusive).",
            "format": "int32",
            "type": "integer"
          },
          "inheritFromBefore": {
            "description": "Whether dimension properties should be extended from the dimensions before or after the newly inserted dimensions. True to inherit from the dimensions before (in which case the start index must be greater than 0), and false to inherit from the dimensions after.",
            "type": "boolean"
          },
          "sheetId": {
            "description": "Required. The ID of the sheet to insert into.",
            "format": "int32",
            "type": "integer"
          },
          "spreadsheetId": {
            "description": "Required. The ID of the spreadsheet to update.",
            "type": "string"
          },
          "startIndex": {
            "description": "Required. The 0-based start index of the insertion (inclusive).",
            "format": "int32",
            "type": "integer"
          }
        },
        "required": [
          "spreadsheetId",
          "sheetId",
          "dimension",
          "startIndex",
          "endIndex"
        ]
      }
    },
    {
      "tool": "update_formulas",
      "description": "Sets formulas in a range of a spreadsheet. Corresponds to spreadsheets.values.update in the REST API: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets.values/update",
      "inputSchema": {
        "type": "object",
        "properties": {
          "formulas": {
            "description": "Required. The data that was read or to be written. This is an array of arrays, the outer array representing all the data and each inner array representing a row. Each item in the inner array corresponds with one cell. Supported value types are: bool, string, and double. Null values will be skipped. To set a cell to an empty value, set the string value to an empty string.",
            "items": {
              "items": {},
              "type": "array"
            },
            "type": "array"
          },
          "range": {
            "description": "Required. The [A1 notation](https://developers.google.com/workspace/sheets/api/guides/concepts.md.txt) of the values to update.",
            "type": "string"
          },
          "spreadsheetId": {
            "description": "Required. The ID of the spreadsheet to update.",
            "type": "string"
          }
        },
        "required": [
          "spreadsheetId",
          "range",
          "formulas"
        ]
      }
    },
    {
      "tool": "update_spreadsheet",
      "description": "Applies one or more updates to the spreadsheet. Corresponds to spreadsheets.batchUpdate in the REST API: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets/batchUpdate The list of possible updates is: - `updateSpreadsheetProperties`: Updates the spreadsheet's properties. - `updateSheetProperties`: Updates a sheet's properties. - `updateDimensionProperties`: Updates dimensions' properties. - `updateNamedRange`: Updates a named range. - `repeatCell`: Repeats a single cell across a range. - `addNamedRange`: Adds a named range. - `deleteNamedRange`: Deletes a named range. - `addSheet`: Adds a sheet. - `deleteSheet`: Deletes a sheet. - `autoFill`: Automatically fills in more data based on existing data. - `cutPaste`: Cuts data from one area and pastes it to another. - `copyPaste`: Copies data from one area and pastes it to another. - `mergeCells`: Merges cells together. - `unmergeCells`: Unmerges merged cells. - `updateBorders`: Updates the borders in a range of cells. - `updateCells`: Updates many cells at once. - `addFilterView`: Adds a filter view. - `appendCells`: Appends cells after the last row with data in a sheet. - `clearBasicFilter`: Clears the basic filter on a sheet. - `deleteDimension`: Deletes rows or columns in a sheet. - `deleteEmbeddedObject`: Deletes an embedded object (e.g, chart, image) in a sheet. - `deleteFilterView`: Deletes a filter view from a sheet. - `duplicateFilterView`: Duplicates a filter view. - `duplicateSheet`: Duplicates a sheet. - `findReplace`: Finds and replaces occurrences of some text with other text. - `insertDimension`: Inserts new rows or columns in a sheet. - `insertRange`: Inserts new cells in a sheet, shifting the existing cells. - `moveDimension`: Moves rows or columns to another location in a sheet. - `updateEmbeddedObjectPosition`: Updates an embedded object's (e.g. chart, image) position. - `pasteData`: Pastes data (HTML or delimited) into a sheet. - `textToColumns`: Converts a column of text into many columns of text. - `updateFilterView`: Updates the properties of a filter view. - `deleteRange`: Deletes a range of cells from a sheet, shifting the remaining cells. - `appendDimension`: Appends dimensions to the end of a sheet. - `addConditionalFormatRule`: Adds a new conditional format rule. - `updateConditionalFormatRule`: Updates an existing conditional format rule. - `deleteConditionalFormatRule`: Deletes an existing conditional format rule. - `sortRange`: Sorts data in a range. - `setDataValidation`: Sets data validation for one or more cells. - `setBasicFilter`: Sets the basic filter on a sheet. - `addProtectedRange`: Adds a protected range. - `updateProtectedRange`: Updates a protected range. - `deleteProtectedRange`: Deletes a protected range. - `autoResizeDimensions`: Automatically resizes one or more dimensions based on the contents of the cells in that dimension. - `addChart`: Adds a chart. - `updateChartSpec`: Updates a chart's specifications. - `updateBanding`: Updates a banded range - `addBanding`: Adds a new banded range - `deleteBanding`: Removes a banded range - `createDeveloperMetadata`: Creates new developer metadata - `updateDeveloperMetadata`: Updates an existing developer metadata entry - `deleteDeveloperMetadata`: Deletes developer metadata - `randomizeRange`: Randomizes the order of the rows in a range. - `addDimensionGroup`: Creates a group over the specified range. - `deleteDimensionGroup`: Deletes a group over the specified range. - `updateDimensionGroup`: Updates the state of the specified group. - `trimWhitespace`: Trims cells of whitespace (such as spaces, tabs, or new lines). - `deleteDuplicates`: Removes rows containing duplicate values in specified columns of a cell range. - `updateEmbeddedObjectBorder`: Updates an embedded object's border. - `addSlicer`: Adds a slicer. - `updateSlicerSpec`: Updates a slicer's specifications. - `addDataSource`: Adds a data source. - `updateDataSource`: Updates a data source. - `deleteDataSource`: Deletes a data source. - `refreshDataSource`: Refreshes one or multiple data sources and associated dbobjects. - `cancelDataSourceRefresh`: Cancels refreshes of one or multiple data sources and associated dbobjects. - `addTable`: Adds a table. - `updateTable`: Updates a table. - `deleteTable`: A request for deleting a table.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "requests": {
            "description": "Required. A list of updates to apply to the spreadsheet. Each request should be a valid spreadsheets.batchUpdate Request object, using the schema documented in: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets/request Requests will be applied in the order they are specified. If any request is not valid, no requests will be applied.",
            "items": {
              "additionalProperties": {
                "description": "Properties of the object."
              },
              "type": "object"
            },
            "type": "array"
          },
          "spreadsheetId": {
            "description": "Required. The ID of the spreadsheet to update.",
            "type": "string"
          },
          "writeControl": {
            "$ref": "#/$defs/WriteControl",
            "description": "Optional. Provides control over how write requests are executed."
          }
        },
        "required": [
          "spreadsheetId",
          "requests"
        ],
        "$defs": {
          "WriteControl": {
            "description": "Provides control over how write requests are executed.",
            "properties": {
              "requiredRevisionId": {
                "description": "The revision ID of the spreadsheet that the write request will be applied to. If this is not the latest revision of the document, the request will not be processed and will return a 400 bad request error. When a required revision ID is returned in a response, it indicates the revision ID of the spreadsheet after the request was applied.",
                "type": "string"
              }
            },
            "type": "object"
          }
        }
      }
    },
    {
      "tool": "update_values",
      "description": "Sets values in a range of a spreadsheet. Corresponds to spreadsheets.values.update in the REST API: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets.values/update",
      "inputSchema": {
        "type": "object",
        "properties": {
          "range": {
            "description": "Required. The [A1 notation](https://developers.google.com/workspace/sheets/api/guides/concepts.md.txt) of the values to update.",
            "type": "string"
          },
          "spreadsheetId": {
            "description": "Required. The ID of the spreadsheet to update.",
            "type": "string"
          },
          "values": {
            "description": "Required. The data that was read or to be written. This is an array of arrays, the outer array representing all the data and each inner array representing a row. Each item in the inner array corresponds with one cell. Supported value types are: bool, string, and double. Null values will be skipped. To set a cell to an empty value, set the string value to an empty string.",
            "items": {
              "items": {},
              "type": "array"
            },
            "type": "array"
          }
        },
        "required": [
          "spreadsheetId",
          "range",
          "values"
        ]
      }
    }
  ]
}

